void reverse_text(char *s) {
    size_t n = 0;
    while (s[n] != '\0') {
        n++;
    }
    if (n < 2) {
        return;
    }
    size_t i = 0;
    size_t j = n - 1;
    while (i < j) {
        char t = s[i];
        s[i] = s[j];
        s[j] = t;
        i++;
        j--;
    }
}

