typedef struct {
    int *data;
    size_t len;
    size_t cap;
} IntVec;

void vec_init(IntVec *v) {
    v->data = NULL;
    v->len = 0;
    v->cap = 0;
}

bool vec_push(IntVec *v, int x) {
    if (v->len == v->cap) {
        size_t newcap = v->cap == 0 ? 4 : v->cap * 2;
        int *bigger = realloc(v->data, newcap * sizeof *bigger);
        if (bigger == NULL) {
            return false;
        }
        v->data = bigger;
        v->cap = newcap;
    }
    v->data[v->len] = x;
    v->len++;
    return true;
}

void vec_free(IntVec *v) {
    free(v->data);
    vec_init(v);
}

